// ---------------------------------------------------------------------------
// preview-artifact.js — builds a single-file, hash-routed interactive preview
// of the whole site (all pages reachable via #/path navigation, no server
// needed), with photos/logo inlined as base64 data URIs so it works as one
// self-contained HTML file. This is for quick interactive review only — the
// real deploy-ready output is /dist, generated by build/generate.js.
// ---------------------------------------------------------------------------
const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");

const config = require("./site.config");

const home = require("./pages/home");
const education = require("./pages/education");
const mediaIndex = require("./pages/media");
const mediaSlugPage = require("./pages/mediaSlug");
const servicesIndex = require("./pages/services");
const servicesSlugPage = require("./pages/servicesSlug");
const academyPage = require("./pages/academy");
const aboutPage = require("./pages/about");
const contactPage = require("./pages/contact");
const instagramPage = require("./pages/instagram");
const legalPage = require("./pages/legal");

const articles = require("./content/articles");
const services = require("./content/services");
const legalDocs = require("./content/legal");

function dataUri(file, mime) {
  const buf = fs.readFileSync(file);
  return `data:${mime};base64,${buf.toString("base64")}`;
}

// Build a config clone whose asset paths point at inlined data URIs, so the
// single HTML file carries its own images instead of referencing /assets/*.
const inlineConfig = JSON.parse(JSON.stringify(config));
inlineConfig.waLink = config.waLink;
inlineConfig.brand.logo.navy = dataUri(path.join(ROOT, "assets", "logo-navy.png"), "image/png");
inlineConfig.brand.logo.white = dataUri(path.join(ROOT, "assets", "logo-white.png"), "image/png");

const PHOTO_FILES = fs.readdirSync(path.join(ROOT, "assets", "photos"));
const photoDataUris = {};
PHOTO_FILES.forEach((file) => {
  photoDataUris[`/assets/photos/${file}`] = dataUri(path.join(ROOT, "assets", "photos", file), "image/jpeg");
});

function inlinePhotoRefs(html) {
  let out = html;
  Object.keys(photoDataUris).forEach((srcPath) => {
    out = out.split(srcPath).join(photoDataUris[srcPath]);
  });
  return out;
}

const routes = [
  { path: "/", title: "Beranda", minimal: false, body: home(inlineConfig) },
  { path: "/instagram/", title: "Instagram", minimal: true, body: instagramPage(inlineConfig) },
  { path: "/education/", title: "Edukasi", minimal: false, body: education(inlineConfig) },
  { path: "/media/", title: "Media & Artikel", minimal: false, body: mediaIndex(inlineConfig) },
  { path: "/services/", title: "Layanan", minimal: false, body: servicesIndex(inlineConfig) },
  { path: "/academy/", title: "Akademi", minimal: false, body: academyPage(inlineConfig) },
  { path: "/about/", title: "Tentang", minimal: false, body: aboutPage(inlineConfig) },
  { path: "/contact/", title: "Kontak", minimal: false, body: contactPage(inlineConfig) },
];
articles.forEach((a) => routes.push({ path: `/media/${a.slug}/`, title: a.title, minimal: false, body: mediaSlugPage(inlineConfig, a) }));
services
  .filter((s) => s.category !== "akademik")
  .forEach((s) => routes.push({ path: `/services/${s.slug}/`, title: s.title, minimal: false, body: servicesSlugPage(inlineConfig, s) }));
legalDocs.forEach((d) => routes.push({ path: `/${d.slug}/`, title: d.title, minimal: false, body: legalPage(inlineConfig, d) }));

const css = fs.readFileSync(path.join(ROOT, "styles", "main.css"), "utf8");
const revealJs = fs.readFileSync(path.join(ROOT, "assets", "scripts", "reveal.js"), "utf8");

// Escape any literal "</script" sequence inside embedded page HTML (e.g. the contact
// page's own inline <script> block) — otherwise the browser's HTML parser ends this
// outer <script> tag early at that substring, regardless of it being inside a JS string.
function safeForInlineScript(jsonString) {
  return jsonString.replace(/<\/script/gi, "<\\/script");
}

const titlesMap = safeForInlineScript(JSON.stringify(Object.fromEntries(routes.map((r) => [r.path, r.title]))));
const pagesMap = safeForInlineScript(JSON.stringify(Object.fromEntries(routes.map((r) => [r.path, inlinePhotoRefs(r.body)]))));
const minimalPaths = safeForInlineScript(JSON.stringify(routes.filter((r) => r.minimal).map((r) => r.path)));
const navItems = safeForInlineScript(JSON.stringify(config.nav));
const waLink = config.waLink();
const whatsappIcon = require("./components/icons").whatsapp();
const instagramIcon = require("./components/icons").instagram();

const html = `<title>${config.brand.name} — Preview</title>
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,500;0,600;0,700;0,800;1,600&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet" />
<style>
${css}

.preview-banner {
  background: var(--navy-900);
  color: var(--white);
  text-align: center;
  font-size: 12.5px;
  font-weight: 700;
  padding: 8px 14px;
  position: relative;
  z-index: 70;
  border-bottom: 2px solid var(--navy-500);
}
</style>

<div class="preview-banner">PREVIEW INTERAKTIF — SEMUA ${routes.length} HALAMAN BISA DIKLIK · Situs asli (deploy-ready) ada di file proyek yang dikirimkan terpisah</div>

<div id="minimalBack" class="container" hidden style="padding-top:18px;">
  <a href="#/" class="small" style="font-weight:700;color:var(--navy-900);">&larr; ${config.brand.name}</a>
</div>

<div id="siteHeader">
  <header class="site-header">
    <div class="container site-header__row">
      <a href="#/" class="brand" aria-label="${config.brand.name} — Beranda">
        <span class="brand__mark"><img src="${inlineConfig.brand.logo.navy}" alt="" width="36" height="52" /></span>
        <span class="brand__word">ORDER<b>.NOTARIS</b></span>
      </a>
      <nav class="nav-desktop" aria-label="Navigasi utama">
        <ul id="navDesktopList"></ul>
      </nav>
      <div class="header-actions">
        <a class="btn btn-wa" href="${waLink}" target="_blank" rel="noopener">${whatsappIcon} WhatsApp</a>
        <button class="nav-toggle" id="navToggle" aria-label="Buka menu" aria-expanded="false" aria-controls="mobileNav">
          ${require("./components/icons").menu()}
        </button>
      </div>
    </div>
  </header>
  <div class="mobile-nav" id="mobileNav">
    <ul class="mobile-nav__list" id="navMobileList"></ul>
    <div class="mobile-nav__cta">
      <a class="btn btn-wa btn-block btn-lg" href="${waLink}" target="_blank" rel="noopener">${whatsappIcon} Chat via WhatsApp</a>
      <a class="btn btn-outline btn-block" href="#/instagram/">${instagramIcon} Kunjungi Instagram</a>
    </div>
  </div>
</div>

<main id="pageRoot"></main>

<div id="siteFooter"></div>
<a class="wa-fab" href="${waLink}" target="_blank" rel="noopener" aria-label="Chat via WhatsApp">${whatsappIcon}<span>Chat WhatsApp</span></a>

<script>
  var TITLES = ${titlesMap};
  var PAGES = ${pagesMap};
  var MINIMAL_PATHS = ${minimalPaths};
  var NAV = ${navItems};

  var navDesktop = document.getElementById('navDesktopList');
  var navMobile = document.getElementById('navMobileList');

  function renderNav(currentPath) {
    var html = NAV.map(function (n) {
      return '<li><a href="#' + n.href + '"' + (n.href === currentPath ? ' aria-current="page"' : '') + '>' + n.label + '</a></li>';
    }).join('');
    navDesktop.innerHTML = html;
    navMobile.innerHTML = html;
  }

  function currentPath() {
    var hash = location.hash.replace(/^#/, '') || '/';
    return hash in PAGES ? hash : '/';
  }

  function render() {
    var p = currentPath();
    var isMinimal = MINIMAL_PATHS.indexOf(p) !== -1;
    document.getElementById('siteHeader').hidden = isMinimal;
    document.getElementById('siteFooter').hidden = isMinimal;
    document.getElementById('minimalBack').hidden = !isMinimal;
    document.title = (TITLES[p] || 'ORDER.NOTARIS') + ' · ORDER.NOTARIS (Preview)';
    document.getElementById('pageRoot').innerHTML = PAGES[p];
    renderNav(p);
    window.scrollTo(0, 0);
    if (window.initReveal) window.initReveal();
  }

  window.addEventListener('hashchange', render);
  document.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    var href = a.getAttribute('href');
    if (href && href.indexOf('#/') === 0) {
      // in-site navigation — handled by hashchange
      return;
    }
  });

  document.getElementById('navToggle').addEventListener('click', function () {
    var menu = document.getElementById('mobileNav');
    var isOpen = menu.classList.toggle('is-open');
    this.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  });

  render();
</script>
<script>
${revealJs.replace("(function () {", "window.initReveal = function () {").replace(/\}\)\(\);\s*$/, "};\nwindow.initReveal();")}
</script>`;

fs.writeFileSync(path.join(ROOT, "preview-artifact.html"), html);
console.log(`Wrote ${path.join(ROOT, "preview-artifact.html")} (${routes.length} routes)`);
